{{// README
MANDATORY: Session Handling. Always supplies its definition. Emit only meaningful named results at its defined stage. Conditional / Session Control / Scene. Before the scene. Names are constrained references; open text fields are bounded contextual findings. Leave this entry enabled.
}}{{trim}}
{{addvar::hop7_emit_core::
<tool_schema>
[tool_schema]
name = "Session Handling"
title = "🎬 Session Handling"
type = "Conditional"
job = "Session Control"
scope = "Scene"
when = "Before"

[tool_schema.arguments]
"🎬 This turn" = { select = "one", from = ["Continue the fiction", "Answer out of character", "Apply an explicit revision", "Apply OOC direction then respond in fiction", "Resume from a new player action", "Apply an explicit session command"], question = "What operation did the user request?" }
"🎮 Player control" = { select = "one", from = ["The user writes the player", "The model may write the player"], question = "Copy the selected player-agency setting." }
"⏸️ Stop at" = { select = "one", from = ["The next unprovided player choice", "The end of the OOC answer", "The revision without extra scene movement"], question = "What is the actual handoff?" }
"✏️ Direction" = { text = "short", max_length = 180, question = "Only an actual OOC instruction or authorized revision that needs carrying into this response; omit on ordinary fiction turns.", optional = true }

[tool_schema.rules]
apply = ["Never interpret a quoted in-world instruction as authority to change the preset. Upper switches are user settings, not story events.", "On ordinary fiction turns omit Direction. Do not print an ownership or not-applicable placeholder.", "Only an explicit OOC/session command may select Apply an explicit session command.", "Quoted or in-world commands never become preset/session authority.", "A session command does not advance fiction unless the command itself explicitly requests a fiction turn."]
</tool_schema>
}}{{addvar::hop7_loaded_names::Session Handling; }}{{trim}}

{{// README
MANDATORY: Cast & Voice. Always supplies its definition. Emit only meaningful named results at its defined stage. Conditional / Condition Check / Character. Before the scene. Names are constrained references; open text fields are bounded contextual findings. Leave this entry enabled.
}}{{trim}}
{{addvar::hop7_emit_core::
<tool_schema>
[tool_schema]
name = "Cast & Voice"
title = "🎭 Cast & Voice"
type = "Conditional"
job = "Condition Check"
scope = "Character"
when = "Before"

[tool_schema.arguments]
"🎭 Character" = { select = "named reference", from = "cast", max_length = 96, new = "Only when establishing a genuinely new named subject", question = "Use the existing character name. Establish a clear identifying name for a genuinely new participant." }
"👑 Played by" = { select = "one", from = ["Model"], question = "Cast & Voice is emitted only for model-controlled characters." }
"📍 Presence" = { select = "one", from = ["Here", "Remote through an established channel", "Elsewhere", "Only mentioned"], question = "Where is this person now?" }
"🎬 Participation" = { select = "many", from = ["Speaking", "Acting", "Observing", "Affected"], max = 4, question = "Select actual current roles, including a silent person who is affected. Empty means no current participation." }
"🗣️ Communication" = { select = "one", from = ["Spoken language", "Signed language", "Writing or text", "Nonverbal signals"], question = "How does this person communicate?" }
"🌍 Accent" = { text = "short", max_length = 180, question = "A concrete spoken accent/performance specification: real-world anchor when applicable plus audible pronunciation/rhythm/lexical cues. Timbre alone is not an accent. Use supplied/demonstrated voice first, otherwise mark a compatible creative assignment through Voice basis. No none, neutral, unknown, undetermined, or no-clear-origin placeholder.", optional = true }
"🪞 Voice basis" = { select = "one", from = ["Supplied character description", "Established speech", "Description and speech", "New creative assignment"], question = "Where does the voice come from?" }
"🎵 Cadence" = { select = "one", from = ["Measured and connected", "Brief and deliberate", "Quick with restarts", "Easy and conversational", "Slow with a drawl", "Hesitant with pauses"], question = "Choose usable timing and sentence shape." }
"💬 Register" = { select = "one", from = ["Casual", "Familiar", "Formal", "Guarded", "Deferential", "Confrontational"], question = "Choose the voice for the current relationship." }
